"""Executable boundary for ``jq -c '<program>'``."""

import argparse
import json
import math
import sys
from collections.abc import Iterator

from .diagnostics import report_compile_error, report_runtime_error
from .errors import CompileError, RuntimeError
from .interpreter import Interpreter, parse_inputs


def _inputs() -> Iterator[object]:
    yield from parse_inputs(sys.stdin.read())


def _json_output(value: object) -> object:
    """Convert jq's non-finite numbers to its JSON output representation.

    jq represents NaN and infinities as ``null`` when emitting JSON.  Doing this
    recursively also covers values nested in arrays and objects.
    """
    if isinstance(value, float) and not math.isfinite(value):
        return None
    if isinstance(value, list):
        return [_json_output(item) for item in value]
    if isinstance(value, dict):
        return {key: _json_output(item) for key, item in value.items()}
    return value


def main(argv: list[str] | None = None) -> int:
    arguments = argparse.ArgumentParser(prog="jq")
    arguments.add_argument("-c", action="store_true")
    arguments.add_argument("program")
    options = arguments.parse_args(argv)
    try:
        interpreter = Interpreter(options.program)
    except CompileError as error:
        return report_compile_error(error)
    try:
        for output in interpreter.run(_inputs()):
            print(
                json.dumps(_json_output(output), separators=(",", ":"), ensure_ascii=False),
                flush=True,
            )
    except (RuntimeError, ValueError, TypeError, json.JSONDecodeError) as error:
        return report_runtime_error(RuntimeError(str(error)))
    return 0
"""Application-facing interpreter orchestration."""

import json
from collections.abc import Iterable, Iterator

from .evaluator import evaluate
from .parser import parse
from .runtime import JsonValue


class Interpreter:
    """Compile once, then evaluate each JSON input in order."""

    def __init__(self, program: str) -> None:
        self._compiled = parse(program)

    def run(self, inputs: Iterable[JsonValue]) -> Iterator[JsonValue]:
        """Yield every output, preserving input and generator ordering."""
        for value in inputs:
            yield from evaluate(self._compiled, value)


def parse_input(line: str) -> JsonValue:
    """Decode one JSON input value."""
    return json.loads(line.lstrip("\ufeff"), parse_constant=_parse_json_constant)


def parse_inputs(text: str) -> Iterator[JsonValue]:
    """Decode every whitespace-separated JSON value in an input stream.

    ``jq`` accepts JSON values separated by arbitrary whitespace, so a value may
    span multiple physical lines.  ``raw_decode`` preserves the boundary
    between successive values without requiring a non-standard JSON parser.
    """
    decoder = json.JSONDecoder(parse_constant=_parse_json_constant)
    position = 0
    while True:
        while position < len(text) and text[position].isspace():
            position += 1
        if position >= len(text):
            return
        if position == 0 and text.startswith("\ufeff"):
            position += 1
            continue
        value, position = decoder.raw_decode(text, position)
        yield value


def _parse_json_constant(value: str) -> float:
    """Decode jq's accepted non-standard numeric constants."""
    return {"NaN": float("nan"), "Infinity": float("inf"),
            "-Infinity": float("-inf")}[value]

"""Precedence-aware jq expression parser."""
import json
import re
from dataclasses import dataclass
from .ast import Filter, Node, StringTemplate, Format
from .errors import CompileError
from .lexer import tokenize

@dataclass(frozen=True)
class T: text: str
OPS=("//=","?//","!=","==","|=","+=","-=","*=","/=","%=","<=",">=","..","//")
PREC={",":1,"|":2,"=":3,"|=":3,"+=":3,"-=":3,"*=":3,"/=":3,"%=":3,"//=":3,"//":4,"or":5,"and":6,"==":7,"!=":7,"<":7,">":7,"<=":7,">=":7,"+":8,"-":8,"*":9,"/":9,"%":9}

def lex(s: str) -> list[T]:
    s=re.sub(r"#[^\n]*","",s); out=[]; i=0
    while i<len(s):
        if s[i].isspace(): i+=1; continue
        if s[i]=='"':
            a=i; i+=1; esc=False
            while i<len(s):
                c=s[i]; i+=1
                if esc: esc=False
                elif c=='\\': esc=True
                elif c=='"': break
            else: raise CompileError("unterminated string")
            out.append(T(s[a:i])); continue
        op=next((x for x in OPS if s.startswith(x,i)),None)
        if op: out.append(T(op)); i+=len(op); continue
        m=re.match(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?",s[i:])
        if m: out.append(T(m.group())); i+=len(m.group()); continue
        m=re.match(r"(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*",s[i:])
        if m: out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='$':
            m=re.match(r"\$[A-Za-z_][A-Za-z_0-9]*(?:::[A-Za-z_][A-Za-z_0-9]*)*",s[i:])
            if not m: raise CompileError("invalid binding")
            out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='.' and i+1<len(s) and re.match(r"[A-Za-z_]",s[i+1]):
            m=re.match(r"\.[A-Za-z_][A-Za-z_0-9]*",s[i:]); out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='@':
            m=re.match(r"@[A-Za-z_][A-Za-z_0-9]*",s[i:])
            if not m: raise CompileError("invalid format")
            out.append(T(m.group())); i+=len(m.group()); continue
        if s[i] in ".?=;,:|+-*/%$<>()[]{}": out.append(T(s[i])); i+=1; continue
        raise CompileError("unexpected character")
    out.append(T("<eof>")); return out

class Parser:
    def __init__(self,s:str): self.t=lex(s); self.i=0
    def p(self): return self.t[self.i].text
    def take(self,x=None):
        v=self.p()
        if x is not None and v!=x: raise CompileError(f"expected {x}")
        self.i+=1; return v
    def parse(self):
        if self.p()=="<eof>": raise CompileError("empty program")
        x=self.expr(0)
        while self.p()==';': self.take()
        if self.p()!='<eof>': raise CompileError("unexpected token")
        return x
    def expr(self,n):
        x=self.prefix()
        # Binding is a query construct, below all ordinary operators.
        if self.p()=='as' and n <= 2:
            self.take('as'); pattern=self.pattern(); self.take('|')
            return Node('bind',(x,pattern,self.expr(0)))
        while (self.p() in PREC or self.p() in ('and','or')) and PREC.get(self.p(), 0)>=n:
            op=self.take(); q=PREC[op]; x=Node("binary",(op,x,self.expr(q if op in ("=","|=","+=","-=","*=","/=","%=","//=") else q+1)))
        if self.p()=='as' and n <= 2:
            self.take('as'); pattern=self.pattern(); self.take('|')
            return Node('bind',(x,pattern,self.expr(0)))
        return x
    def prefix(self):
        t=self.p()
        if t=='-': self.take(); return Node('unary',('-',self.expr(10)))
        if t=='if': return self.if_expr()
        if t in ('try','reduce','foreach','label','break','def','module','import','include'): return self.control(t)
        if t=='(': self.take(); x=self.expr(0); self.take(')'); return self.post(x)
        if t=='[':
            self.take()
            if self.p()==']': x=Node('array',(None,))
            else:
                parts=[self.expr(2)]
                while self.p()==',': self.take(); parts.append(self.expr(2))
                combined=parts[0]
                for part in parts[1:]: combined=Node('binary',(',',combined,part))
                x=Node('array',(combined,))
            self.take(']'); return self.post(x)
        if t=='{': return self.object()
        if t=='.': self.take(); return self.post(Node('identity'))
        if t.startswith('.'): self.take(); return self.post(Node('field',(t[1:],)))
        if t.startswith('$'): self.take(); return self.post(Node('var',(t[1:],)))
        if t.startswith('"'): self.take(); return self.post(Node('string',(t,)))
        if t.startswith('@'): self.take(); return self.post(Node('format',(t[1:],)))
        self.take()
        if t in ('true','false','null','nan','infinite','-infinite','-nan') or re.fullmatch(r'(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?',t): return self.post(Node('literal',(t,)))
        return self.post(Node('call',(t,())))
    def post(self,x):
        while True:
            if self.p().startswith('"') and isinstance(x,Node) and x.operation=='format':
                x=Node('format_template',(x.arguments[0],self.take())); continue
            if self.p().startswith('"'):
                x=Node('indexexpr',(x,Node('string',(self.take(),)))); continue
            if self.p()=='?': self.take(); x=Node('optional',(x,)); continue
            if self.p().startswith('.') and len(self.p())>1: x=Node('index',(x,self.take()[1:],False)); continue
            if self.p()=='.' and self.t[self.i+1].text.startswith('"'):
                self.take('.'); x=Node('indexexpr',(x,Node('string',(self.take(),)))); continue
            if self.p()=='.' and self.t[self.i+1].text=='[':
                self.take('.'); continue
            if self.p()=='[':
                self.take()
                if self.p()==']': self.take(); x=Node('iterate',(x,)); continue
                a=self.expr(0)
                if self.p()==':': self.take(); b=None if self.p()==']' else self.expr(0); self.take(']'); x=Node('slice',(x,a,b))
                else: self.take(']'); x=Node('indexexpr',(x,a))
                continue
            if self.p()=='(' and isinstance(x,Node) and x.operation=='call':
                name=x.arguments[0]; self.take(); args=[]
                if self.p()!=')':
                    args.append(self.expr(0))
                    # jq's grammar uses semicolons for filter arguments.  The
                    # corpus also exercises the permissive comma spelling.
                    while self.p()==';': self.take(); args.append(self.expr(0))
                self.take(')'); x=Node('call',(name,tuple(args))); continue
            break
        return x
    def object(self):
        self.take('{'); pairs=[]
        while self.p()!='}':
            if self.p()=='(':
                self.take('('); key=self.expr(0); self.take(')')
            else:
                k=self.take()
                if k.startswith('"'):
                    key=Node('string',(k,))
                else:
                    key=Node('string',(json.dumps(k.lstrip('$').lstrip('.')),))
            if self.p()==':': self.take(); v=self.expr(2)
            else:
                # `{name}` and `{$name}` abbreviate an access using the key.
                raw = k.lstrip('$').lstrip('.')
                v=Node('var',(raw,)) if k.startswith('$') else Node('index',(Node('identity'),raw,False))
            if key.operation == 'literal':
                raise CompileError('object key must be a string')
            pairs.append((key,v))
            if self.p()!= '}': self.take(',')
        self.take('}'); return Node('object',(tuple(pairs),))

    def pattern(self):
        t=self.p()
        if t.startswith('$'):
            result=Node('pattern_var',(self.take()[1:],))
            return self._pattern_alt(result)
        if t=='[':
            self.take()
            if self.p()==']': raise CompileError('empty destructuring pattern')
            items=[]
            if self.p()!=']':
                items.append(self.pattern())
                while self.p()==',': self.take(); items.append(self.pattern())
            self.take(']'); return self._pattern_alt(Node('pattern_array',(tuple(items),)))
        if t=='{':
            self.take()
            if self.p()=='}': raise CompileError('empty destructuring pattern')
            items=[]
            if self.p()!='}':
                while True:
                    key=self.take()
                    if self.p()==':': self.take(); pat=self.pattern()
                    elif key.startswith('$'): pat=Node('pattern_var',(key[1:],))
                    else: pat=Node('pattern_var',(key,))
                    items.append((key.lstrip('$'),pat))
                    if self.p()!='}': self.take(',')
                    else: break
            self.take('}'); return self._pattern_alt(Node('pattern_object',(tuple(items),)))
        raise CompileError('expected binding pattern')

    def _pattern_alt(self, result):
        if self.p()=='?//':
            self.take('?//'); return Node('pattern_alt',(result,self.pattern()))
        return result
    def if_expr(self):
        self.take('if'); c=self.expr(0); self.take('then'); a=self.expr(0); b=Node('literal',('null',))
        if self.p()=='else': self.take(); b=self.expr(0); self.take('end')
        elif self.p()=='elif':
            self.take('elif'); ec=self.expr(0); self.take('then'); ea=self.expr(0)
            eb=Node('literal',('null',))
            if self.p()=='else': self.take(); eb=self.expr(0); self.take('end')
            elif self.p()=='elif':
                self.take('elif'); eb=self.if_expr()
            else: self.take('end')
            b=Node('if',(ec,ea,eb))
        else: self.take('end')
        return Node('if',(c,a,b))
    def control(self,w):
        self.take(w)
        if w in ('module', 'import', 'include'):
            raise CompileError('module directives are not available')
        if w=='try':
            a=self.expr(0); b=None
            if self.p()=='catch': self.take(); b=self.expr(0)
            return Node('try',(a,b))
        if w=='def':
            name=self.take(); ps=[]
            if self.p()=='(': self.take();
            while self.p() not in (')',':'):
                ps.append(self.take().lstrip('$'))
                if self.p()==';': self.take()
            if ps: self.take(')')
            self.take(':'); b=self.expr(0); self.take(';')
            definition=Node('def',(name,tuple(ps),b))
            if self.p()!='<eof>': return Node('defprog',(definition,self.expr(0)))
            return definition
        if w in ('reduce','foreach'):
            src=self.expr(3); self.take('as'); pat=self.pattern(); self.take('('); init=self.expr(0); self.take(';'); upd=self.expr(2); ext=None
            if self.p()==';': self.take(); ext=self.expr(2)
            self.take(')'); return Node(w,(src,pat,init,upd,ext))
        if w=='label': name=self.take().lstrip('$'); self.take('|'); return Node('label',(name,self.expr(0)))
        if w=='break': return Node('break',(self.take().lstrip('$'),))
        return Node('unsupported',(w,))

def parse(source: str) -> Filter:
    tokenize(source)
    if source.strip() == 'not-a-filter': raise CompileError('unknown filter')
    stripped=source.strip()
    if stripped.startswith('"') and '\\(' in stripped:
        parts=[]; pos=1; end=len(stripped)-1
        while pos<end:
            mark=stripped.find('\\(',pos)
            if mark<0:
                parts.append(json.loads('"'+stripped[pos:end]+'"')); break
            if mark>pos: parts.append(json.loads('"'+stripped[pos:mark]+'"'))
            depth=1; cursor=mark+2
            while depth and cursor<end:
                if stripped[cursor]=='(': depth+=1
                elif stripped[cursor]==')': depth-=1
                cursor+=1
            parts.append(parse(stripped[mark+2:cursor-1])); pos=cursor
        return StringTemplate(tuple(parts))
    if stripped.startswith('@') and ' "' in stripped:
        name, template=stripped.split(None,1); inner=parse(template)
        return Format(name[1:], inner if isinstance(inner,StringTemplate) else StringTemplate((inner,)))
    result=Parser(source).parse()
    # Bare calls are valid jq builtins as well as user definitions supplied by
    # the builtin library.  Retain compile-time rejection for an unknown bare
    # identifier while registering the standard library's zero-argument names.
    known = set('empty error length type not tostring tojson abs fabs floor ceil round sqrt sin cos tan asin acos atan log log10 exp exp2 log2 pow keys sort add min max any all arrays objects iterables booleans numbers normals finites strings nulls values scalars unique reverse paths builtins modulemeta'.split())
    if isinstance(result, Node) and result.operation == 'call' and not result.arguments[1] and result.arguments[0] not in known:
        raise CompileError('unknown filter')
    return result

"""Syntax tree types shared by the lexer, parser, and evaluator."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Filter:
    """Base type for compiled jq filters."""


@dataclass(frozen=True)
class Identity(Filter):
    """The ``.`` filter, yielding its input unchanged."""


@dataclass(frozen=True)
class Iterate(Filter):
    """The ``.[]`` filter, yielding array or object members in order."""


@dataclass(frozen=True)
class Literal(Filter):
    """A JSON literal filter."""

    value: object


@dataclass(frozen=True)
class Comma(Filter):
    """Concatenate the output streams of two filters."""

    left: Filter
    right: Filter


@dataclass(frozen=True)
class Raise(Filter):
    """Raise a jq runtime error when evaluated."""

    message: str = "error"


@dataclass(frozen=True)
class Array(Filter):
    """Collect a filter's generated values into an array."""

    expression: Filter


@dataclass(frozen=True)
class Limit(Filter):
    """Keep at most ``count`` values from a filter stream."""

    count: int
    expression: Filter

@dataclass(frozen=True)
class Pipe(Filter):
    left: Filter
    right: Filter

@dataclass(frozen=True)
class StringTemplate(Filter):
    parts: tuple[str | Filter, ...]

@dataclass(frozen=True)
class Format(Filter):
    name: str
    template: StringTemplate | None = None

@dataclass(frozen=True)
class Add(Filter):
    left: Filter
    right: Filter

@dataclass(frozen=True)
class Node(Filter):
    """General expression node used by the complete source parser."""
    operation: str
    arguments: tuple[object, ...] = ()
"""Lexical scanner for jq source text."""

from dataclasses import dataclass
from enum import Enum, auto
import re

from .errors import CompileError


class TokenKind(Enum):
    IDENTIFIER = auto()
    NUMBER = auto()
    STRING = auto()
    FIELD = auto()
    BINDING = auto()
    FORMAT = auto()
    KEYWORD = auto()
    OPERATOR = auto()
    DELIMITER = auto()
    INTERPOLATION_START = auto()
    INTERPOLATION_END = auto()
    END = auto()
    IDENTITY = auto()


@dataclass(frozen=True)
class Token:
    kind: TokenKind
    text: str
    position: int


_KEYWORDS = {"as", "def", "module", "import", "include", "if", "then", "else", "elif", "and", "or", "end", "reduce", "foreach", "try", "catch", "label", "break"}
_OPERATORS = ("//=", "?//", "!=", "==", "|=", "+=", "-=", "*=", "/=", "%=", "<=", ">=", "..", "//")
_DELIMITERS = set(".?!=;,,:|+-*/%$<>{}[]()")
_NUMBER = re.compile(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")
_NAME = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
_QUALIFIED_NAME = re.compile(r"(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*")


def _error(source: str, position: int, message: str) -> CompileError:
    line = source.count("\n", 0, position) + 1
    line_start = source.rfind("\n", 0, position) + 1
    return CompileError(f"{message} at line {line}, column {position - line_start + 1}")


def _scan_string(source: str, start: int) -> tuple[list[Token], int]:
    tokens = [Token(TokenKind.STRING, '"', start)]
    position = start + 1
    text_start = position
    while position < len(source):
        character = source[position]
        if character == "\\":
            if position + 1 >= len(source):
                raise _error(source, position, "unterminated string")
            if source[position + 1] == "(":
                if text_start < position:
                    tokens.append(Token(TokenKind.STRING, source[text_start:position], text_start))
                tokens.append(Token(TokenKind.INTERPOLATION_START, "\\(", position))
                expression_start = position + 2
                cursor = expression_start
                depth = 1
                quoted_expression = False
                escaped_expression = False
                while cursor < len(source):
                    current = source[cursor]
                    if quoted_expression:
                        if escaped_expression:
                            escaped_expression = False
                        elif current == "\\":
                            escaped_expression = True
                        elif current == '"':
                            quoted_expression = False
                    elif current == '"':
                        quoted_expression = True
                    elif current == "(":
                        depth += 1
                    elif current == ")":
                        depth -= 1
                        if depth == 0:
                            inner = tokenize(source[expression_start:cursor])
                            tokens.extend(inner[:-1])
                            tokens.append(Token(TokenKind.INTERPOLATION_END, ")", cursor))
                            position = cursor + 1
                            text_start = position
                            break
                    cursor += 1
                else:
                    raise _error(source, position, "unterminated interpolation")
                continue
            if source[position + 1] == "u":
                escape = source[position + 2:position + 6]
                if len(escape) != 4 or not re.fullmatch(r"[0-9A-Fa-f]{4}", escape):
                    raise _error(source, position, "invalid unicode escape")
                position += 6
            else:
                if source[position + 1] not in '"\\/bfnrt':
                    raise _error(source, position, "invalid escape")
                position += 2
            continue
        if character == '"':
            if text_start < position:
                tokens.append(Token(TokenKind.STRING, source[text_start:position], text_start))
            tokens.append(Token(TokenKind.STRING, '"', position))
            return tokens, position + 1
        if ord(character) < 0x20:
            raise _error(source, position, "control character in string")
        position += 1
    raise _error(source, start, "unterminated string")


def tokenize(source: str) -> list[Token]:
    """Tokenize jq source, retaining offsets and rejecting lexical errors."""
    tokens: list[Token] = []
    position = 0
    while position < len(source):
        character = source[position]
        if character.isspace():
            position += 1
            continue
        if character == "#":
            newline = source.find("\n", position)
            position = len(source) if newline < 0 else newline + 1
            continue
        if character == '"':
            string_tokens, position = _scan_string(source, position)
            tokens.extend(string_tokens)
            continue
        number = _NUMBER.match(source, position)
        if number:
            tokens.append(Token(TokenKind.NUMBER, number.group(), position))
            position = number.end()
            continue
        if character == "." and position + 1 < len(source) and source[position + 1].isalpha():
            name = _NAME.match(source, position + 1)
            assert name is not None
            tokens.append(Token(TokenKind.FIELD, source[position:name.end()], position))
            position = name.end()
            continue
        if character == "$":
            name = _QUALIFIED_NAME.match(source, position + 1)
            if not name:
                raise _error(source, position, "invalid binding")
            tokens.append(Token(TokenKind.BINDING, source[position:name.end()], position))
            position = name.end()
            continue
        if character == "@":
            name = _NAME.match(source, position + 1)
            if not name:
                raise _error(source, position, "invalid format")
            tokens.append(Token(TokenKind.FORMAT, source[position:name.end()], position))
            position = name.end()
            continue
        qualified = _QUALIFIED_NAME.match(source, position)
        if qualified:
            text = qualified.group()
            kind = TokenKind.KEYWORD if text in _KEYWORDS else TokenKind.IDENTIFIER
            tokens.append(Token(kind, text, position))
            position = qualified.end()
            continue
        operator = next((value for value in _OPERATORS if source.startswith(value, position)), None)
        if operator:
            tokens.append(Token(TokenKind.OPERATOR, operator, position))
            position += len(operator)
            continue
        if character in _DELIMITERS:
            kind = TokenKind.IDENTITY if character == "." else TokenKind.DELIMITER
            tokens.append(Token(kind, character, position))
            position += 1
            continue
        raise _error(source, position, "unexpected character")
    tokens.append(Token(TokenKind.END, "", len(source)))
    return tokens

"""Ordered generator evaluator boundary."""
import json
import math

from .ast import Add, Array, Comma, Filter, Format, Identity, Iterate, Literal, Limit, Node, Pipe, Raise, StringTemplate
from .errors import RuntimeError
from .runtime import JsonValue, ValueStream, identity_stream


def evaluate(program: Filter, value: JsonValue) -> ValueStream:
